/* Kovai Streets: geosites.js
 * Step G6: missions, jobs and places on the real map.
 * W(x,z) converts a position written for the grid world into the real map:
 * - inside a mission site from js/geosites_data.js (generated by tools/geo/place_sites.py) the whole site moves as one piece,
 *   turned in quarter turns for the jetty, so every mission layout stays exactly as designed;
 * - anywhere else each axis is scaled so the grid world (about +-1100 units around Town Hall) fills the ring road, Town Hall going to Central Kovai
 *   (same as grid_to_real in tools/geo/place_sites.py).
 * Fictional sites never sit on real landmarks (see geodata/validation/sites_report.md).
 * Classic script, loaded after core.js and geosites_data.js. Shares top-level declarations with the other game scripts.
 */
'use strict';

const SITES_BY_R=GEO_SITES.filter(s=>s.old).slice().sort((a,b)=>a.r-b.r);   // small spots win over big areas
function siteAt(x,z){for(const s of SITES_BY_R)if(Math.hypot(x-s.old[0],z-s.old[1])<=s.r)return s;return null}
function siteMap(s,x,z){const dx=x-s.old[0],dz=z-s.old[1],u=[[1,0],[0,1],[-1,0],[0,-1]][s.rot||0];return[s.x+u[0]*dx-u[1]*dz,s.z+u[1]*dx+u[0]*dz]}
function gridToReal(x,z){const fx=clamp((x-TH.x)/1100,-1,1),fz=clamp((z-TH.z)/1100,-1,1);return[200+(fx<0?fx*2000:fx*1700),-300+(fz<0?fz*1050:fz*1700)]}
function W(x,z){const s=siteAt(x,z);return s?siteMap(s,x,z):gridToReal(x,z)}
function WO(x,z){const p=W(x,z);return{x:p[0],z:p[1]}}
function SITE(id){return GEO_SITES.find(s=>s.id===id)}
/* heading of the old +x axis inside a site (only the jetty is turned) */
function siteHeading(s,h){return h+(s?-(s.rot||0)*Math.PI/2:0)}
/* real OSM buildings inside an area site are not drawn and get no colliders */
const GW_CLEAR=GEO_SITES.filter(s=>s.clear>0);
function gwCleared(b){if(!GW_CLEAR.length)return false;const r=b.pts;let cx=0,cz=0;for(const q of r){cx+=q[0];cz+=q[1]}cx/=r.length;cz/=r.length;
  for(const s of GW_CLEAR)if(Math.hypot(cx-s.x,cz-s.z)<s.clear)return true;return false}

/* is (x, z) inside a real building outline? (uses chunk data that has been downloaded; unknown areas count as free) */
function geoInBuilding(x,z){const S=GWLD.index?GWLD.index.size_m:1000,d=GWLD.data.get(Math.floor(x/S)+','+Math.floor(z/S));if(!d)return false;
  for(const b of d.buildings||[]){const r=b.pts;if(Math.abs(r[0][0]-x)>80||Math.abs(r[0][1]-z)>80||gwCleared(b))continue;let ins=false;for(let i=0,j=r.length-1;i<r.length;j=i++){const a=r[i],c=r[j];if((a[1]>z)!==(c[1]>z)&&x<(c[0]-a[0])*(z-a[1])/(c[1]-a[1])+a[0])ins=!ins}if(ins)return true}return false}
/* nearest sidewalk point to (x, z): beside the nearest ordinary road, on the side facing (x, z), moved closer to the road if a building is in the way */
function geoSidewalk(x,z){if(!NAV.ready)return[x,z];let best=null,bd=1e18;for(const k of navNear(x,z,300)){const e=NAV.E[k];if(e.layer||e.bridge)continue;const p=e.pts;
    for(let i=1;i<p.length;i++){const a=p[i-1],b=p[i],dx=b[0]-a[0],dz=b[1]-a[1],L=dx*dx+dz*dz||1,t=clamp(((x-a[0])*dx+(z-a[1])*dz)/L,0,1),qx=a[0]+dx*t,qz=a[1]+dz*t,d=(qx-x)**2+(qz-z)**2;
      if(d<bd){bd=d;const l=Math.sqrt(L),nx=dz/l,nz=-dx/l,s=(x-qx)*nx+(z-qz)*nz>=0?1:-1;best=null;
        for(const[o,ss]of[[e.w/2+2.4,s],[e.w/2+1.2,s],[e.w/2+2.4,-s],[e.w/2+1.2,-s],[e.w/2-0.8,s]]){const px=qx+nx*o*ss,pz=qz+nz*o*ss;if(!geoInBuilding(px,pz)){best=[px,pz];break}}if(!best)best=[qx+nx*(e.w/2-0.8)*s,qz+nz*(e.w/2-0.8)*s]}}}return best||[x,z]}

/* ---------- jobs on real streets ---------- */
function geoRoadPoint(nx,nz,minD,maxD){const c=navNear(nx,nz,maxD);let p=null;for(let t=0;t<80&&c.length;t++){const e=NAV.E[c[(Math.random()*c.length)|0]];if(e.layer||e.bridge||e.w<5)continue;
    const q=e.pts[(e.pts.length/2)|0],d=Math.hypot(q[0]-nx,q[1]-nz);const s=geoSidewalk(q[0],q[1]);p={x:s[0],z:s[1]};if(d>=minD&&d<=maxD)return p}return p||{x:nx,z:nz}}
/* race: 7 checkpoints about 160 m apart along real roads */
function geoRaceSteps(o){const steps=[];let n=navNearestNode(o.x,o.z,true),prev=-1,acc=0,len=0,px=o.x,pz=o.z;
  for(let g=0;g<400&&steps.length<7;g++){const out=NAV.OUT[n].filter(k=>NAV.E[k].t!==prev&&!NAV.E[k].layer);const k=out.length?rpick(out):NAV.OUT[n][0];if(k==null)break;const e=NAV.E[k];prev=n;n=e.t;acc+=e.len;
    if(acc>=160){const q=NAV.nodes[n];len+=Math.hypot(q[0]-px,q[1]-pz)+acc*0.3;px=q[0];pz=q[1];acc=0;steps.push({x:q[0],z:q[1],txt:`Checkpoint ${steps.length+1} of 7`})}}
  return{steps,len}}
/* a car that runs from the player along real roads (chase jobs, the courier, Kathir's scooter) */
function geoFleeCar(type,x,z,color,cruise){const c=navNear(x,z,250).filter(k=>!NAV.E[k].layer&&NAV.E[k].len>15);if(!c.length)return spawnVehicle(type,x,z,0,color);
  let k=c[0],bd=1e9;for(const q of c){const n=NAV.nodes[NAV.E[q].f],d=Math.hypot(n[0]-x,n[1]-z);if(d<bd){bd=d;k=q}}const e=NAV.E[k],two=!!(VT[type]&&VT[type].two),lane=navLane(e,two),w=navWps(e,lane,0);
  const v=spawnVehicle(type,w[0].x,w[0].z,navDir(e,false),color);v.ai={geo:true,e:k,lane,two,base:cruise,cruise,wps:w.slice(1),turnWp:null,blockT:0,stuck:0,hitT:0,i:0,j:0,dx:0,dz:0,reckless:true,flee:true};
  v.speed=cruise*0.6;return v}
/* the tail (mission 8) on the real map: Gandhipuram Central Bus Stand -> hotel stop by VOC Park -> construction office on the north-east edge of the city
   -> meeting a few hundred metres on. Positions in game metres inside the compact city (tools/geo/build_city.py). */
const TAIL_START=[180,-230],TAIL_HOTEL=[1570,170],TAIL_OFFICE=[1800,950];   /* Central Kovai -> East Junction -> Greenfield (REBUILD_SPEC.md) */
function geoTailRoute(){const meet=geoRoadPoint(TAIL_OFFICE[0],TAIL_OFFICE[1],450,800),legs=[[TAIL_START,TAIL_HOTEL,{stop:20,id:'hotel'}],[TAIL_HOTEL,TAIL_OFFICE,{stop:9,id:'office'}],[TAIL_OFFICE,[meet.x,meet.z],{stop:1e9,id:'meet'}]],pts=[];
  for(const[a,b,st]of legs){const r=navRoute(a[0],a[1],b[0],b[1],true)||navRoute(a[0],a[1],b[0],b[1],false);const seg=r?r.pts:[a,b];for(let i=pts.length?1:0;i<seg.length;i++)pts.push({x:seg[i][0],z:seg[i][1]});pts.push(Object.assign({x:seg[seg.length-1][0],z:seg[seg.length-1][1]},st))}
  for(let i=pts.length-1;i>0;i--)if(Math.hypot(pts[i].x-pts[i-1].x,pts[i].z-pts[i-1].z)<3&&!pts[i].stop)pts.splice(i,1);return pts}

/* ---------- structures for the mission sites ---------- */
function geoWall(x0,z0,x1,z1,h,c){addBox(B_PLAIN,Math.abs(x1-x0)||0.4,h,Math.abs(z1-z0)||0.4,(x0+x1)/2,h/2,(z0+z1)/2,c);
  addCollider(Math.min(x0,x1)-(x0===x1?0.2:0),Math.min(z0,z1)-(z0===z1?0.2:0),Math.max(x0,x1)+(x0===x1?0.2:0),Math.max(z0,z1)+(z0===z1?0.2:0),h)}
/* Ghat Wolves compound (replaces the hill-village hideout): walled yard, two sheds, a water tank, crates */
function buildHideout(cx,cz){const C='#8e877a',H=3;addFlat(B_SIDE,cx-26,cz-20,cx+26,cz+20,0.04,'#cfc6b2',2.5);
  geoWall(cx-26,cz-20,cx-5,cz-20,H,C);geoWall(cx+5,cz-20,cx+26,cz-20,H,C);geoWall(cx-26,cz+20,cx+26,cz+20,H,C);geoWall(cx-26,cz-20,cx-26,cz+20,H,C);geoWall(cx+26,cz-20,cx+26,cz+20,H,C);
  wallW(cx-14,cz+10,16,10,5,0,'#9c8f7a');wallW(cx+15,cz+11,12,8,4.5,0,'#a39581');addBox(B_PLAIN,17,0.3,11,cx-14,5.15,cz+10,'#5e5a52');addBox(B_PLAIN,13,0.3,9,cx+15,4.65,cz+11,'#5e5a52');
  addG(B_PLAIN,GEO.cyl,cx+20,6,cz-12,'#3f5130',0,0,0,2.2,4,2.2);for(const s of[-1,1])addBox(B_PLAIN,0.3,8,0.3,cx+20+s*1.6,2,cz-12,'#555');addCollider(cx+18,cz-14,cx+22,cz-10,8);
  for(const[x,z]of[[-8,-6],[4,-10],[10,2],[-18,-8],[0,6]]){addBox(B_PLAIN,1.6,1.4,1.6,cx+x,0.7,cz+z,'#7a5a3a');addCollider(cx+x-0.8,cz+z-0.8,cx+x+0.8,cz+z+0.8,1.4)}
  const s=textPlane('KEEP OUT',4,0.7,'#3f5130','#f2d13a');s.position.set(cx,3.6,cz-20.3);s.rotation.y=Math.PI}
/* quarry yard (replaces the hilltop viewpoint deal): fenced gravel yard, sand piles, a container, a crusher shed */
function buildDealYard(cx,cz){addFlat(B_SIDE,cx-24,cz-18,cx+24,cz+18,0.04,'#b7a98f',2.5);for(const[x0,z0,x1,z1]of[[-24,-18,-8,-18],[8,-18,24,-18],[-24,18,24,18],[-24,-18,-24,18],[24,-18,24,18]])geoWall(cx+x0,cz+z0,cx+x1,cz+z1,1.8,'#6f6a60');
  for(const[x,z,r]of[[-14,8,6],[-4,10,4.5],[12,-6,5]])addG(B_PLAIN,GEO.cone8,cx+x,r*0.45,cz+z,'#c2a36b',0,0,0,r,r*0.9,r);
  addBox(B_PLAIN,12,2.6,2.6,cx+14,1.3,cz+9,'#1d6fa5');addCollider(cx+8,cz+7.7,cx+20,cz+10.3,2.6);wallW(cx-16,cz-9,9,7,6,0,'#8a8578');
  const s=textPlane('KOVAI STONE QUARRY YARD',8,0.8,'#2b2d42','#f2d13a');s.position.set(cx,2.6,cz-18.3);s.rotation.y=Math.PI}
/* fictional jetty on the edge of Chinna Kulam (Valankulam): deck along the site's turned +x axis, boats moored at the end */
function buildJetty(s){const u=[[1,0],[0,1],[-1,0],[0,-1]][s.rot],L=128,Wd=5,y=1.4,cx=s.x+u[0]*L/2,cz=s.z+u[1]*L/2,ax=Math.abs(u[0])>0;
  addBox(B_PLAIN,ax?L:Wd,0.25,ax?Wd:L,cx,y-0.12,cz,'#8b6b4a');for(let d=4;d<=L;d+=6)for(const o of[-2.3,2.3])addG(B_PLAIN,GEO.cyl8,s.x+u[0]*d-u[1]*o,(y-6)/2,s.z+u[1]*d+u[0]*o,'#5d4030',0,0,0,0.18,y+6,0.18);
  for(const o of[-2.45,2.45]){const x=cx-u[1]*o,z=cz+u[0]*o;addBox(B_PLAIN,ax?L:0.1,0.1,ax?0.1:L,x,y+0.9,z,'#6d4c41');addCollider(x-(ax?L/2:0.15),z-(ax?0.15:L/2),x+(ax?L/2:0.15),z+(ax?L/2:0.15),y+1,y-0.3)}
  SURF.push({minX:Math.min(s.x,s.x+u[0]*L)-(ax?0:Wd/2),maxX:Math.max(s.x,s.x+u[0]*L)+(ax?0:Wd/2),minZ:Math.min(s.z,s.z+u[1]*L)-(ax?Wd/2:0),maxZ:Math.max(s.z,s.z+u[1]*L)+(ax?Wd/2:0),h:()=>y});
  const h=Math.atan2(u[0],u[1])+Math.PI/2;for(const[d,o,t]of[[136,-4,'speedboat'],[136,4,'speedboat'],[120,12,'fishboat']]){const v=spawnVehicle(t,s.x+u[0]*d-u[1]*o,s.z+u[1]*d+u[0]*o,h);v.keep=true}
  PLACES.push({n:'the lakeside jetty',x:s.x,z:s.z})}

/* everything that needs the road graph: sites, gangs, reels, rampages, stunt ramps, shop and hospital pads */
function initGeoSites(){const S=id=>SITE(id);
  BUILD.mill(S('mill_podanur').x,S('mill_podanur').z);BUILD.mill(S('mill_singanallur').x,S('mill_singanallur').z);BUILD.mill(S('mill_kovai').x,S('mill_kovai').z);BUILD.mall(S('mall').x,S('mall').z);
  buildPoliceStation();buildGodown();buildSafehouse();buildHideout(S('hideout').x,S('hideout').z);buildDealYard(S('dealyard').x,S('dealyard').z);buildJetty(S('jetty'));
  /* stunt ramps on long, nearly north-south or east-west stretches of main road, spread apart */
  /* straight runs are measured along whole roads, across the junction points where side streets join */
  const straight=(p,j,i)=>{for(let k=j+1;k<i;k++)if(segDist(p[k][0],p[k][1],p[j],p[i])>1.5)return false;return true};
  const picks=[];for(const r of NAV.roads){if(!(r.cls==='trunk'||r.cls==='primary')||r.layer||r.bridge||r.pts.length<2)continue;const p=r.pts;
    for(let j=0;j<p.length-1&&picks.length<RAMPS.length;){let i=j+1;while(i+1<p.length&&straight(p,j,i+1))i++;
      const dx=p[i][0]-p[j][0],dz=p[i][1]-p[j][1],l=Math.hypot(dx,dz),ax=Math.abs(dx)>Math.abs(dz),off=Math.min(Math.abs(dx),Math.abs(dz))/(l||1),a=[p[j][0]+dx*0.2,p[j][1]+dz*0.2];j=i;
      if(l<140||off>0.12)continue;/* long enough to land on the same straight */if(picks.some(q=>Math.hypot(q.a[0]-a[0],q.a[1]-a[1])<600))continue;picks.push({a,d:ax?[Math.sign(dx),0]:[0,Math.sign(dz)]})}}
  picks.forEach((q,k)=>{RAMPS[k].a=q.a;RAMPS[k].d=q.d});RAMPS.length=picks.length;buildRamps();RAMPS_READY=true;
  for(const k of GWLD.live.keys())if(!GWLD.queue.includes(k))GWLD.queue.push(k);/* rebuild loaded chunks so street furniture keeps the ramp landing zones clear */
  finish(B_WIN,winMat,true);for(let i=1;i<4;i++)finish(B_FAC[i],FACMAT[i],true);finish(B_SHOP,shopMat,true);finish(B_SIDE,sideMat,false);finish(B_PLAIN,plainMat,true);buildPalms();
  for(const f of FLAMES){const m=new THREE.Mesh(GEO.sph,MBasic('#ffb347'));m.position.set(f.x,f.y,f.z);m.scale.setScalar(0.22);scene.add(m);f.m=m}
  /* gang hangouts: the real positions of the old hangout corners, on a sidewalk */
  for(const sp of gangSpots){const[x,z]=W(sp.i*CELL+sp.sx*10.5,sp.j*CELL+sp.sz*10.5);[sp.gx,sp.gz]=geoSidewalk(x,z);spawnGang(sp)}
  for(const r of RAMPAGES){if(r.x0==null){r.x0=r.x;r.z0=r.z}[r.x,r.z]=geoSidewalk(...W(r.x0,r.z0));if(r.sp)r.sp.position.set(r.x,1.6,r.z)}
  /* hospital: the nearest real hospital to Town Hall (OSM), on its sidewalk; heal pad and respawn point */
  const hs=GEO_POIS.filter(p=>p.kind==='hospital');let h=hs[0]||{x:0,z:0};for(const p of hs)if(Math.hypot(p.x,p.z)<Math.hypot(h.x,h.z))h=p;[HOSP.x,HOSP.z]=geoSidewalk(h.x,h.z);
  const pad=(x,z,col)=>{const r=new THREE.Mesh(new THREE.RingGeometry(2.6,3.4,32),new THREE.MeshBasicMaterial({color:col,transparent:true,opacity:0.8,side:THREE.DoubleSide}));r.rotation.x=-Math.PI/2;r.position.set(x,0.3,z);scene.add(r)};
  pad(HOSP.x,HOSP.z,0xff4d4d);pad(SHOP.x,SHOP.z,0x7fb8ff);for(const[k,x,z]of[['hosp',HOSP.x,HOSP.z],['gun',SHOP.x,SHOP.z]]){const s=iconSprite(k,x,3.6,z,2.6);s.userData.y=3.6;zoneSprites.push(s)}
  createReels();GEO_SITES_READY=true}
let GEO_SITES_READY=false,RAMPS_READY=false;
